/** AdminAPI provides advanced APIs for debugging and analysis with admin privilege. */
export interface AdminAPI {
  /** DescribeWorkflowExecution returns information about the internal states of workflow execution. */
  DescribeWorkflowExecution(request: DescribeWorkflowExecutionRequest): Promise<DescribeWorkflowExecutionResponse>;
  /** DescribeHistoryHost returns information about the internal states of a history host. */
  DescribeHistoryHost(request: DescribeHistoryHostRequest): Promise<DescribeHistoryHostResponse>;
  /** DescribeShardDistribution returns information about shard distribution */
  DescribeShardDistribution(request: DescribeShardDistributionRequest): Promise<DescribeShardDistributionResponse>;
  /** CloseShard closes shard. */
  CloseShard(request: CloseShardRequest): Promise<CloseShardResponse>;
  /** RemoveTask removes task. */
  RemoveTask(request: RemoveTaskRequest): Promise<RemoveTaskResponse>;
  /** ResetQueue resets queue. */
  ResetQueue(request: ResetQueueRequest): Promise<ResetQueueResponse>;
  /** DescribeQueue describes queue. */
  DescribeQueue(request: DescribeQueueRequest): Promise<DescribeQueueResponse>;
  /**
   * Returns the raw history of specified workflow execution.
   * It fails with 'EntityNotExistError' if specified workflow execution in unknown to the service.
   * StartEventId defines the beginning of the event to fetch. The first event is inclusive.
   * EndEventId and EndEventVersion defines the end of the event to fetch. The end event is exclusive.
   */
  GetWorkflowExecutionRawHistoryV2(
    request: GetWorkflowExecutionRawHistoryV2Request,
  ): Promise<GetWorkflowExecutionRawHistoryV2Response>;
  /** GetReplicationMessages returns new replication tasks since the read level provided in the token. */
  GetReplicationMessages(request: GetReplicationMessagesRequest): Promise<GetReplicationMessagesResponse>;
  /** GetDLQReplicationMessages return replication messages based on DLQ info. */
  GetDLQReplicationMessages(request: GetDLQReplicationMessagesRequest): Promise<GetDLQReplicationMessagesResponse>;
  /** GetDomainReplicationMessages returns new domain replication tasks since last retrieved task id. */
  GetDomainReplicationMessages(
    request: GetDomainReplicationMessagesRequest,
  ): Promise<GetDomainReplicationMessagesResponse>;
  /** ReapplyEvents applies stale events to the current workflow and current run. */
  ReapplyEvents(request: ReapplyEventsRequest): Promise<ReapplyEventsResponse>;
  /** AddSearchAttribute whitelist search attribute in request. */
  AddSearchAttribute(request: AddSearchAttributeRequest): Promise<AddSearchAttributeResponse>;
  /** DescribeCluster returns information about Cadence cluster. */
  DescribeCluster(request: DescribeClusterRequest): Promise<DescribeClusterResponse>;
  /** CountDLQMessages returns message count in DLQ. */
  CountDLQMessages(request: CountDLQMessagesRequest): Promise<CountDLQMessagesResponse>;
  /** ReadDLQMessages returns messages from DLQ. */
  ReadDLQMessages(request: ReadDLQMessagesRequest): Promise<ReadDLQMessagesResponse>;
  /** PurgeDLQMessages purges messages from DLQ. */
  PurgeDLQMessages(request: PurgeDLQMessagesRequest): Promise<PurgeDLQMessagesResponse>;
  /** MergeDLQMessages merges messages from DLQ. */
  MergeDLQMessages(request: MergeDLQMessagesRequest): Promise<MergeDLQMessagesResponse>;
  /** RefreshWorkflowTasks refreshes all tasks of a workflow. */
  RefreshWorkflowTasks(request: RefreshWorkflowTasksRequest): Promise<RefreshWorkflowTasksResponse>;
  /** ResendReplicationTasks requests replication tasks from remote cluster and apply tasks to current cluster. */
  ResendReplicationTasks(request: ResendReplicationTasksRequest): Promise<ResendReplicationTasksResponse>;
  /** GetCrossClusterTasks return cross cluster tasks based on cluster name. */
  GetCrossClusterTasks(request: GetCrossClusterTasksRequest): Promise<GetCrossClusterTasksResponse>;
  /** RespondCrossClusterTasksCompleted responds the result of processing cross cluster tasks. */
  RespondCrossClusterTasksCompleted(
    request: RespondCrossClusterTasksCompletedRequest,
  ): Promise<RespondCrossClusterTasksCompletedResponse>;
  /** GetDynamicConfig returns values associated with a specified dynamic config parameter. */
  GetDynamicConfig(request: GetDynamicConfigRequest): Promise<GetDynamicConfigResponse>;
  /** UpdateDynamicConfig is used to update one or more values associated with a specified dynamic config parameter. */
  UpdateDynamicConfig(request: UpdateDynamicConfigRequest): Promise<UpdateDynamicConfigResponse>;
  /** RestoreDynamicConfig is used to remove one or all values associated with a specified dynamic config parameter. */
  RestoreDynamicConfig(request: RestoreDynamicConfigRequest): Promise<RestoreDynamicConfigResponse>;
  /** ListDynamicConfig returns all dynamic config parameters and associated values. */
  ListDynamicConfig(request: ListDynamicConfigRequest): Promise<ListDynamicConfigResponse>;
  /** DeleteWorkflow is used to delete a workflow with given domainName, workflowID and runID */
  DeleteWorkflow(request: DeleteWorkflowRequest): Promise<DeleteWorkflowResponse>;
  /** MaintainCorruptWorkflow deletes a workflow if its history is corrupt due to underlying DB issues (e.g. Cassandra resurrections) */
  MaintainCorruptWorkflow(request: MaintainCorruptWorkflowRequest): Promise<MaintainCorruptWorkflowResponse>;
  /** GetIsolationGroups */
  GetGlobalIsolationGroups(request: GetGlobalIsolationGroupsRequest): Promise<GetGlobalIsolationGroupsResponse>;
  /** UpdateGlobalIsolationGroups */
  UpdateGlobalIsolationGroups(
    request: UpdateGlobalIsolationGroupsRequest,
  ): Promise<UpdateGlobalIsolationGroupsResponse>;
  /** GetDomainIsolationGroups */
  GetDomainIsolationGroups(request: GetDomainIsolationGroupsRequest): Promise<GetDomainIsolationGroupsResponse>;
  /** UpdateDomainIsolationGroups */
  UpdateDomainIsolationGroups(
    request: UpdateDomainIsolationGroupsRequest,
  ): Promise<UpdateDomainIsolationGroupsResponse>;
  /** GetDomainAsyncWorkflowConfiguraton */
  GetDomainAsyncWorkflowConfiguraton(
    request: GetDomainAsyncWorkflowConfiguratonRequest,
  ): Promise<GetDomainAsyncWorkflowConfiguratonResponse>;
  /** UpdateDomainAsyncWorkflowConfiguraton */
  UpdateDomainAsyncWorkflowConfiguraton(
    request: UpdateDomainAsyncWorkflowConfiguratonRequest,
  ): Promise<UpdateDomainAsyncWorkflowConfiguratonResponse>;
  /** UpdateTaskListPartitionConfig is called to update the partition config of a task list in the database */
  UpdateTaskListPartitionConfig(
    request: UpdateTaskListPartitionConfigRequest,
  ): Promise<UpdateTaskListPartitionConfigResponse>;
}

